import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"閟宫","description":"","frontmatter":{"title":"閟宫","date":"2026-11-10T00:00:00.000Z","seq":35,"categories":["美文","诗经"],"collection":"《诗经 · 颂》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·颂/閟宫.md","filePath":"blogs/诗经·颂/閟宫.md"}'),o={name:"blogs/诗经·颂/閟宫.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="閟宫" tabindex="-1">閟宫 <a class="header-anchor" href="#閟宫" aria-label="Permalink to &quot;閟宫&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　鲁颂·駉之什</p><div class="poem"><p class="poem-stanza">閟宫有侐，实实枚枚。赫赫姜嫄，其德不回。上帝是依，无灾无害。</p><p class="poem-stanza">弥月不迟，是生后稷。降之百福。黍稷重穋，稙稚菽麦。奄有下国，俾民稼穑。</p><p class="poem-stanza">有稷有黍，有稻有秬。奄有下土，缵禹之绪。后稷之孙，实维大王。</p><p class="poem-stanza">居岐之阳，实始剪商。至于文武，缵大王之绪，致天之届，于牧之野。</p><p class="poem-stanza">无二无虞，上帝临女。敦商之旅，克咸厥功。王曰叔父，建尔元子，俾侯于鲁。</p><p class="poem-stanza">大启尔宇，为周室辅。乃命鲁公，俾侯于东。锡之山川，土田附庸。</p><p class="poem-stanza">周公之孙，庄公之子。龙旂承祀。六辔耳耳。春秋匪解，享祀不忒。</p><p class="poem-stanza">皇皇后帝！皇祖后稷！享以骍牺，是飨是宜。降福既多，周公皇祖，亦其福女。</p><p class="poem-stanza">秋而载尝，夏而楅衡，白牡骍刚。牺尊将将，毛炰胾羹。笾豆大房，万舞洋洋。</p><p class="poem-stanza">孝孙有庆。俾尔炽而昌，俾尔寿而臧。保彼东方，鲁邦是尝。不亏不崩，不震不腾。</p><p class="poem-stanza">三寿作朋，如冈如陵。公车千乘，朱英绿縢。二矛重弓。公徒三万，贝胄朱綅。</p><p class="poem-stanza">烝徒增增，戎狄是膺，荆舒是惩，则莫我敢承！俾尔昌而炽，俾尔寿而富。</p><p class="poem-stanza">黄发台背，寿胥与试。俾尔昌而大，俾尔耆而艾。万有千岁，眉寿无有害。</p><p class="poem-stanza">泰山岩岩，鲁邦所詹。奄有龟蒙，遂荒大东。至于海邦，淮夷来同。</p><p class="poem-stanza">莫不率从，鲁侯之功。保有凫绎，遂荒徐宅。至于海邦，淮夷蛮貊。</p><p class="poem-stanza">及彼南夷，莫不率从。莫敢不诺，鲁侯是若。天锡公纯嘏，眉寿保鲁。</p><p class="poem-stanza">居常与许，复周公之宇。鲁侯燕喜，令妻寿母。宜大夫庶士，邦国是有。</p><p class="poem-stanza">既多受祉，黄发儿齿。徂徠之松，新甫之柏。是断是度，是寻是尺。</p><p class="poem-stanza">松桷有舄，路寝孔硕，新庙奕奕。奚斯所作，孔曼且硕，万民是若。</p></div>',3)])])}const d=s(o,[["render",c]]);export{z as __pageData,d as default};
